ben: Draft TS snippet: ```ts
// resume.ts
import Redwood from '@redwood/inference';
const c = new Redwood();
async function* resumeStream(prompt: string, resumeToken?: string){
  let token = resumeToken;
  while(true){
    const stream = await c.stream({prompt, resume_token: token});
    for await(const chunk of stream){
      yield chunk.text;
      token = chunk.resume_token ?? token;
    }
    if(!token) break;
  }
}
```

li: Python retry + resume helpers: ```py
# helpers.py
import time, uuid, base64, json
import requests

def idempotent_retry(max_tries=3):
  def deco(f):
    def wrap(*a, **kw):
      rid = str(uuid.uuid4())
      for i in range(max_tries):
        try:
          headers = kw.pop('headers', {})
          headers.update({'X-Request-Id': rid})
          return f(*a, headers=headers, **kw)
        except (requests.ConnectionError, requests.Timeout):
          if i==max_tries-1: raise
          time.sleep(0.5*(2**i))
    return wrap
  return deco

def encode_resume(obj): return base64.b64encode(json.dumps(obj).encode()).decode()
```

